def _load_gaussian(pairs):
    keys = tuple(key for key, _ in pairs)
    if keys != _SERIAL_KEYS_GAUSSIAN:
        raise ValueError(
            "GaussianMixture JSON must have exactly the serialized keys "
            "in the serialized order"
        )
    data = _convert(pairs)

